__NUXT_JSONP__("/desarrollo-sostenible/noticias/ethos_senala_que_candidatos_presidenciales_no_tienen_propuestas_solidas_1", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q){return {data:[{post:{slug:"ethos_senala_que_candidatos_presidenciales_no_tienen_propuestas_solidas_1",title:"Ethos señala que candidatos presidenciales no tienen propuestas sólidas",date:"2024-05-08T22:47:33.587Z",img:"https:\u002F\u002Fucarecdn.com\u002F4b2d5250-d3a8-4036-976d-3329abca5f39\u002F","img-alt":"Candidatas presidenciales 2024",autor:"Juan Carlos Cortés",link:"https:\u002F\u002Fwww.proceso.com.mx\u002Fnacional\u002F2024\u002F5\u002F8\u002Fethos-senala-que-candidatos-presidenciales-no-tienen-propuestas-solidas-328599.html",category:"desarrollo-sostenible",extracto:"Especialistas analizaron y contrastaron las propuestas de los tres candidatos presidenciales en materia de corrupción, cambio climático y finanzas públicas, temas en donde contrastaron la falta de claridad del financiamiento en las propuestas hechas.",toc:[{id:e,depth:f,text:g},{id:h,depth:f,text:i}],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"A un mes de la elección presidencial, directores de Ethos, organización no gubernamental y especialistas en políticas públicas, presentaron su análisis de las propuestas de los tres candidatos presidenciales, el trabajo resaltó la falta de propuestas sólidas en la financiación de los proyectos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Los especialistas analizaron y contrastaron las propuestas de los tres candidatos presidenciales en materia de corrupción, cambio climático y finanzas públicas, temas en dónde contrastaron la falta de claridad del financiamiento en las propuestas hechas por los políticos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En materia de finanzas, los especialistas contrastaron las propuestas de los tres candidatos; expusieron que Claudia Sheinbaum, candidata de la coalición Sigamos Haciendo Historia, así como Xóchilt Gálvez, aspirante presidencial por parte de la Coalición Fuerza y Corazón por México, no buscan generar una reforma fiscal."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Explicaron que Sheinbaum Pardo busca tener mayor eficiencia en recaudación fiscal, también brindar más apoyos a programas sociales, así como la mejora en salarios."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Por su parte, Xóchilt Gálvez ha propuesto eliminar el Impuesto Sobre la Renta (ISR) a quien gane menos de 15 mil pesos, propone una pensión universal y la tarjeta Mi Salud."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Jorge Álvarez Máynez, candidato presidencial por Movimiento Ciudadano (MC) ha propuesto durante su campaña una Reforma Fiscal, además de buscar combatir la evasión de impuestos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Sin embargo, resaltaron que, en todas las propuestas, ninguna de las candidatas explica cómo subrogará estas propuestas, ya que de llevarlas a cabo sólo generarían presiones al gasto público."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"De las tres propuestas, los especialistas resaltaron que el único candidato que propuso una Reforma Fiscal es Jorge Álvarez Máynez."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Que de acuerdo a sus recomendaciones es necesaria una Reforma Fiscal integral, además de que los gobiernos estatales mejores su recaudación predial, con ello poder subrogar los gastos públicos y programas sociales."}]},{type:a,value:c},{type:b,tag:j,props:{id:e},children:[{type:b,tag:k,props:{ariaHidden:l,href:"#anticorrupci%C3%B3n-candidatos-con-propuestas-cortas-",tabIndex:m},children:[{type:b,tag:n,props:{className:[o,p]},children:[]}]},{type:a,value:g}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La directora de Finanzas Públicas de Ethos, Dalia Toledo, afirmó que el combate a la Corrupción es un tema muy politizado, sin embargo, las propuestas de los candidatos presidenciales se han quedado cortas en alcanzar una solución."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La especialista, también, aseguró que en el actual gobierno el sistema anticorrupción no se tuvo la voluntad política para echarlo adelante, por lo que recomendó que para avanzar en este tema se necesitan situaciones multifactoriales, sin embargo, una de las importantes es la autonomía de las instituciones."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Asimismo, Lilia Alvarado, directora general de Ethos Innovación en Políticas Públicas, pidió principal atención a la propuesta de crear una Agencia Anticorrupción de la candidata Claudia Sheinbaum, ya que dependería exclusivamente del Ejecutivo.  "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“No tendría que preocupar de Claudia Sheinbaum es la Agencia Anticorrupción porque se plantea que esta agencia dependa del Ejecutivo, en ese sentido no estaría arreglando nada, simplemente estaría profundizando esas carencias: falta de autonomía, falta de independencia y control desde el Ejecutivo”, indicó."}]},{type:a,value:c},{type:b,tag:j,props:{id:h},children:[{type:b,tag:k,props:{ariaHidden:l,href:"#cambio-clim%C3%A1tico-en-agendas-pero-sin-propuesta-econ%C3%B3mica",tabIndex:m},children:[{type:b,tag:n,props:{className:[o,p]},children:[]}]},{type:a,value:i}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Laura Delalande, directora de Desarrollo Sostenible e Inclusión de Ethos, detalló que en la agenda de los aspirantes presidenciales deben entrar tres grandes temas, la primera es la crisis hídrica, que además del problema ambiental que representa, también se ha politizado por los candidatos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La segunda, es la crisis alimentaria, ya que uno de los principales efectos de la sequía es que afecta la producción del cultivo."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La tercera crisis, es de salud, el cambio climático genera más insectos que pueden transmitir enfermedades como el dengue, problema que, en el 2023, documentaron, fue de cuatro veces de más casos que el año anterior."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Respecto a los candidatos, Laura Delalande dijo que Claudia Sheinbaum propone mejorar la eficiencia energética de la empresa paraestatales de CFE y Pemex, sin embargo, propone que la producción de energía siga basada en producción de combustibles fósiles, así que se usen energías limpias sin ser su eje rector."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Por su parte, Xóchitl Gálvez su propuesta de transición energética está basada en las energías renovables; algo que los especialistas vieron positivo, ya que aborda la gestión del agua, la dignificación del campo y es la única candidata que habla de un sistema de alertas tempranas para prever los riesgos en el cambio climático.  "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Jorge Álvarez Máynez tiene una propuesta basada en energías limpias, además les pareció interesante que propone reducir combustibles fósiles y cerrar algunas refinerías del país."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Tras su evaluación, consideraron que los tres candidatos buscan en su agenda la energía y el agua, sin embargo, pese a que tienen esa agenda ambiental sólo uno habló del financiamiento."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“El problema que tenemos en cuando a la infraestructura en México se necesita una inversión pública cuantiosa y pues implican una palabra prohibida en elecciones: Reforma Fiscal, el candidato Máynez es el único que abordó ese tema”, dijo."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fethos_senala_que_candidatos_presidenciales_no_tienen_propuestas_solidas_1",extension:".md",createdAt:q,updatedAt:q}}],fetch:{},mutations:[]}}("text","element","\n","p","anticorrupción-candidatos-con-propuestas-cortas-",3,"ANTICORRUPCIÓN: CANDIDATOS CON PROPUESTAS CORTAS  ","cambio-climático-en-agendas-pero-sin-propuesta-económica","CAMBIO CLIMÁTICO EN AGENDAS, PERO SIN PROPUESTA ECONÓMICA","h3","a","true",-1,"span","icon","icon-link","2024-10-02T22:32:44.090Z")));